            return str(data.get('status', '')).lower()
        except (ValueError, SyntaxError, TypeError, AttributeError):
            return ''

    filtered_readings['status'] = filtered_readings['payload'].apply(get_status)
    fault_count = (filtered_readings['status'] == 'fault').sum()

